{
  imports = [ inputs.hermes-agent.homeManagerModules.default ];

  programs.hermes-agent.enable = true;   # CLI hermes на PATH

  services.hermes-agent = {
    enable = true;
    gateway.enable = true;  # если нужен шлюз (Telegram/Discord) — вопрос к сэру
